INSERT INTO public.regulation_articles (id, chapter_id, code, title, content, content_type, sort_order) VALUES
('chuong-iii-ieu-11', 'qclv-chuong-iii', 'Điều 11', 'Quyền, nghĩa vụ, trách nhiệm của viên chức, người lao động:', '1. Được bảo đảm về điều kiện làm việc, được đào tạo nâng cao trình độ chuyên môn nghiệp vụ và được hưởng các quyền lợi theo quy định pháp luật;

2. Có quyền đề xuất đóng góp ý kiến, các biện pháp để thực hiện hiệu quả nhiệm vụ được giao;

3. Có trách nhiệm thực hiện và hoàn thành nhiệm vụ được giao, chấp hành nghiêm quy định pháp luật, chính sách hiện hành và quy chế làm việc của Ban QLDA;

4. Chịu trách nhiệm cá nhân trước Tổ trưởng/Lãnh đạo phòng/Ban Giám đốc Ban QLDA và trước pháp luật về ý kiến đề xuất, tiến độ, chất lượng, hiệu quả của từng công việc được giao; về hình thức, thể thức, trình tự và thủ tục ban hành văn bản và quy trình giải quyết công việc được phân công theo dõi;

5. Thực hiện các quy định của pháp luật về viên chức, hợp đồng lao động, các quy định của Ban QLDA tỉnh và của phòng;

6. Thực hiện tốt mối quan hệ phối hợp công tác với các viên chức và người lao động trong các phòng; xây dựng và thực hiện chương trình công tác mà cá nhân đề ra; thường xuyên trau dồi kiến thức, học tập nâng cao trình độ chuyên môn, nghiệp vụ, rèn luyện đạo đức, lối sống;

7. Có trách nhiệm bảo quản, sử dụng tiết kiệm, hiệu quả tài sản của Ban QLDA;

8. Bảo vệ bí mật nhà nước, bí mật công tác và các nội dung bảo mật theo đúng quy định của pháp luật và theo Quy chế của Ban QLDA;

9. Tuân thủ đúng nội quy, quy chế của đơn vị;

10. Quyền và nghĩa vụ đối với lao động hợp đồng của Ban QLDA: Thực hiện theo điều khoản hợp đồng ký kết;

11. Viên chức, NLĐ không được tham gia, can thiệp vào các quyết định có xung đột lợi ích với bản thân, người thân; phải báo cáo lãnh đạo Ban khi có nguy cơ xung đột lợi ích theo quy định PCTN.', 'text', 6),
('chuong-iv-ieu-12', 'qclv-chuong-iv', 'Điều 12', 'Cách thức giải quyết công việc', '1. Giám đốc và các Phó Giám đốc điều hành công việc trên cơ sở chương trình, kế hoạch công tác của Ban QLDA; tình hình thực tế; yêu cầu chỉ đạo của UBND tỉnh, các sở, ban, ngành; và các nhiệm vụ đột xuất (nếu có);

2. Giám đốc, Phó Giám đốc chủ trì họp, làm việc với lãnh đạo các cơ quan, tổ chức có liên quan để tham khảo ý kiến trước khi quyết định những vấn đề quan trọng hoặc còn vướng mắc chưa xử lý được ngay;

3. Khi trình hồ sơ giải quyết công việc cho Lãnh đạo Ban, cán bộ thụ lý hồ sơ phải có Tờ trình/Văn bản và đầy đủ hồ sơ kèm theo; đồng thời thực hiện xử lý công việc thông qua phần mềm hồ sơ quản lý công việc (TDO);

4. Lãnh đạo phòng, viên chức, người lao động chỉ được xử lý công việc sau khi lãnh đạo Ban QLDA đã có ý kiến chỉ đạo cụ thể trên phiếu trình hoặc thông qua phần mềm hồ sơ quản lý công việc.', 'text', 1),
('chuong-iv-ieu-13', 'qclv-chuong-iv', 'Điều 13', 'Trách nhiệm của các phòng trực thuộc trong việc trình Lãnh đạo Ban QLDA giải quyết hồ sơ công việc', '1. Các phòng trực thuộc chỉ trình Giám đốc, Phó Giám đốc những vấn đề thuộc phạm vi giải quyết của Giám đốc, Phó Giám đốc khi có đủ các hồ sơ theo quy định.

2. Khi trình Giám đốc, Phó Giám đốc, các phòng trực thuộc có nhiệm vụ:

a) Thẩm định về mặt thủ tục: Nếu hồ sơ công việc trình không đúng theo quy định, phải hướng dẫn ngay cho cá nhân, đơn vị đã nộp hồ sơ để bổ sung thủ tục đầy đủ. Đối với những vấn đề cần giải quyết gấp, các phòng trực thuộc làm phiếu báo cho đơn vị trình bổ sung thêm hồ sơ, đồng thời báo cho Giám đốc, Phó Giám đốc phụ trách được biết;', 'text', 2),
('chuong-iv-ieu-14', 'qclv-chuong-iv', 'Điều 14', 'Tiếp nhận, xử lý và ban hành văn bản', '1. Quy trình tiếp nhận, xử lý và ban hành văn bản phải tuân thủ theo quy định pháp luật về công tác văn thư và Quy định tiếp nhận, xử lý, ban hành văn bản tại Ban QLDA;

2. Các phòng chuyên môn, cán bộ Ban QLDA phải kiểm tra và chịu trách nhiệm về độ chính xác của văn bản; Đối với dự toán/dự toán điều chỉnh, báo cáo, … có file excel đính kèm, thì bắt buộc phải gửi file pdf để ban hành kèm theo;	3. Trưởng bộ phận chuyên môn phải kiểm tra và chịu trách nhiệm về hình thức, thể thức, kỹ thuật trình bày và thủ tục ban hành văn bản theo đúng quy định của pháp luật, đồng thời phải ký nháy vào văn bản tham mưu ban hành.', 'text', 3),
('chuong-iv-ieu-15', 'qclv-chuong-iv', 'Điều 15', 'Quy định về sử dụng dấu của cơ quan', '1. Việc quản lý, sử dụng con dấu được thực hiện theo quy định của pháp luật về quản lý và sử dụng con dấu.

2. Nhân viên văn thư có trách nhiệm bảo quản, sử dụng con dấu theo đúng quy định và có trách nhiệm.

a) Không giao con dấu cho người khác khi chưa được phép bằng văn bản của người có thẩm quyền;', 'text', 4),
('chuong-v-ieu-16', 'qclv-chuong-v', 'Điều 16', 'Quan hệ công tác giữa Ban QLDA với UBND tỉnh, Chủ tịch UBND tỉnh', '1. Chịu sự chỉ đạo, kiểm tra, giám sát trực tiếp của UBND tỉnh, Chủ tịch UBND tỉnh về thực hiện chức năng, nhiệm vụ được giao;

2. Trình cấp quyết định đầu tư phê duyệt các nội dung thuộc trách nhiệm của chủ đầu tư theo nhiệm vụ được giao và theo quy định của pháp luật;

3. Báo cáo định kỳ hoặc đột xuất về tình hình triển khai thực hiện các dự án được giao quản lý; đề xuất biện pháp xử lý những vấn đề vượt quá thẩm quyền giải quyết của mình;

4. Giải trình các nội dung cần thiết theo yêu cầu của UBND tỉnh, Chủ tịch UBND tỉnh;

5. Phối hợp với các cơ quan, đơn vị chức năng của UBND tỉnh trong việc thực hiện các nhiệm vụ quản lý dự án.', 'text', 1),
('chuong-v-ieu-17', 'qclv-chuong-v', 'Điều 17', 'Quan hệ công tác giữa Ban QLDA với các Sở, ban ngành thuộc tỉnh', '1. Khi giải quyết vấn đề thuộc thẩm quyền của mình nhưng có liên quan đến chức năng của các Sở, ban, ngành khác thì chủ động tham khảo ý kiến các cơ quan đó;

2. Đối với các vấn đề vượt thẩm quyền và khả năng giải quyết của Ban QLDA tỉnh hoặc những vấn đề đã được bàn bạc nhưng còn có ý kiến khác nhau giữa các sở, ban ngành, UBND các phường/xã thì báo cáo Chủ tịch/Phó Chủ tịch UBND tỉnh (trưởng Ban chỉ đạo dự án) phụ trách lĩnh vực giải quyết.

3. Báo cáo, giải trình về tình hình thực hiện quản lý dự án khi được yêu cầu, về sự cố công trình, an toàn trong xây dựng với cơ quan nhà nước có thẩm quyền và đề xuất biện pháp phối hợp xử lý những vấn đề vượt quá thẩm quyền;

4. Chịu sự kiểm tra, giám sát của cơ quan nhà nước có thẩm quyền theo quy định của pháp luật. Chủ động phối hợp chặt chẽ và thường xuyên với các sở, ban, ngành và đoàn thể, với chủ đầu tư dự án để giải quyết công việc kịp thời.', 'text', 2),
('chuong-v-ieu-18', 'qclv-chuong-v', 'Điều 18', 'Quan hệ công tác giữa Ban QLDA với UBND các phường/xã.', '1. Giám đốc Ban QLDA làm việc trực tiếp với Chủ tịch UBND các phường/xã để giải quyết các vấn đề cụ thể của phường/xã có liên quan đến chức năng của Ban QLDA. Khi Giám đốc ủy quyền cho các Phó Giám đốc, Trưởng/Phụ trách các phònglàm việc với Chủ tịch UBND các phường/xã thì những ý kiến của người được ủy quyền được coi là ý kiến của Giám đốc;

2. Trường hợp đề nghị của UBND các phường/xã liên quan đến nhiều ngành, thì Ban QLDA phải chủ động phối hợp với các sở, ban, ngành liên quan để xử lý. Trường hợp các cơ quan không thống nhất hoặc còn có ý kiến khác nhau thì báo cáo Chủ tịch/Phó Chủ tịch UBND tỉnh (trưởng Ban chỉ đạo dự án) phụ trách lĩnh vực giải quyết;

3. Phối hợp với UBND cấp xã trong việc thực hiện công tác bồi thường, giải phóng mặt bằng, tái định cư khi dự án có yêu cầu về thu hồi đất để xây dựng; quản lý hành chính, bảo đảm an ninh, trật tự, an toàn của cộng đồng trong quá trình thực hiện dự án và bàn giao công trình vào khai thác, sử dụng.', 'text', 3),
('chuong-v-ieu-19', 'qclv-chuong-v', 'Điều 19', 'Quan hệ công tác giữa Ban QLDA với chủ đầu tư các dự án thực hiện quản lý dự án, chủ quản lý sử dụng công trình', '1. Thực hiện các quyền, nghĩa vụ đối với các chủ đầu tư, chịu sự kiểm tra, giám sát của chủ đầu tư trong quá trình thực hiện quản lý các dự án theo hợp đồng ký kết và theo quy định của pháp luật có liên quan;

2. Phối hợp với chủ quản lý sử dụng công trình khi lập, phê duyệt nhiệm vụ thiết kế xây dựng công trình, trong quá trình tổ chức thực hiện dự án, nghiệm thu, bàn giao công trình xây dựng hoàn thành vào vận hành, sử dụng (kể cả việc thực hiện bảo hành công trình theo quy định);

3. Bàn giao công trình xây dựng hoàn thành cho chủ đầu tư hoặc chủ quản lý sử dụng theo quy định của pháp luật; quản lý công trình xây dựng hoàn thành trong thời gian chưa xác định được đơn vị quản lý sử dụng công trình theo yêu cầu của người quyết định đầu tư;

4. Thực hiện các nhiệm vụ tư vấn quản lý dự án của chủ đầu tư theo ủy quyền và theo quy định của pháp luật có liên quan.', 'text', 4),
('chuong-v-ieu-20', 'qclv-chuong-v', 'Điều 20', 'Quan hệ công tác giữa Ban QLDA với nhà thầu', '1. Tổ chức lựa chọn nhà thầu thực hiện các gói thầu thuộc dự án do mình làm chủ đầu tư hoặc được thuê làm tư vấn quản lý dự án; đàm phán, ký kết và thực hiện hợp đồng với nhà thầu được lựa chọn theo quy định của pháp luật;

2. Thực hiện các quyền, nghĩa vụ của chủ đầu tư đối với nhà thầu xây dựng theo quy định của hợp đồng xây dựng và quy định của pháp luật có liên quan;

3. Tiếp nhận, xử lý theo thẩm quyền hoặc kiến nghị cấp có thẩm quyền giải quyết các đề xuất, vướng mắc của nhà thầu trong quá trình thực hiện.', 'text', 5)
